// Judgments:
// 1. Expected CMA policy path and its effect on VLTX
// 2. VLTX volatility and Jan-2028 call pricing (IV vs realized)
globalThis.a=nodes.open({task:"What is the expected CMA policy path (timing, direction, likelihood) relevant to VLTX, and what does it imply for VLTX's value?"});
globalThis.b=nodes.open({task:"What are VLTX's Jan-2028 call prices/implied volatility versus VLTX realized/historical volatility, and are the calls cheap or rich on volatility alone?"});
const r=await Promise.all([a.result(),b.result()]);
return r.map(x=>x.line+"\n"+0);

// Judgments:
// 1. What is the expected CMA policy path through 2027 and its implications for VLTX's holdings?
// 2. What is the earnings outlook for VLTX's holdings through 2027, and what valuation do they carry?
globalThis.a=nodes.open({task:"What is the expected CMA policy path through 2027, and how does it bear on valuation of VLTX's holdings?"});
globalThis.b=nodes.open({task:"What is the earnings outlook through 2027 for VLTX's holdings, and what valuation multiples do they carry?"});
const [x,y]=await Promise.all([a.result(),b.result()]);
return [x,y].map(r=>r.line+"\n"+"").join("\n")+"\n"+await read(x.ref)+"\n----\n"+await read(y.ref);

// Judgments: (1) valuation case (n2), (2) option pricing (n3). Children already open.
const r = await Promise.all([nodes.handle("n2").result(), nodes.handle("n3").result()]);
return r.map(x=>read(x.ref));
